type Handler struct {
	r InternalRegistry
	c *config.DefaultProvider
}

func NewHandler(r InternalRegistry) *Handler {
	return &Handler{
		r: r,
		c: r.Config(),
	}
}

func (h *Handler) SetPublicRoutes(public *httprouterx.RouterPublic, corsMiddleware func(http.Handler) http.Handler) {
	public.OPTIONS(TokenPath, corsMiddleware(http.HandlerFunc(h.handleOptions)).ServeHTTP)
	public.POST(TokenPath, corsMiddleware(http.HandlerFunc(h.oauth2TokenExchange)).ServeHTTP)

	public.GET(AuthPath, h.oAuth2Authorize)
	public.POST(AuthPath, h.oAuth2Authorize)
	public.GET(LogoutPath, h.performOidcFrontOrBackChannelLogout)
	public.POST(LogoutPath, h.performOidcFrontOrBackChannelLogout)

	public.GET(DefaultLoginPath, h.fallbackHandler("", "", http.StatusOK, config.KeyLoginURL))
	public.GET(DefaultConsentPath, h.fallbackHandler("", "", http.StatusOK, config.KeyConsentURL))
	public.GET(DefaultLogoutPath, h.fallbackHandler("", "", http.StatusOK, config.KeyLogoutURL))
	public.GET(DefaultPostLogoutPath, h.fallbackHandler(
		"You logged out successfully!",
		"The Default Post Logout URL is not set which is why you are seeing this fallback page. Your log out request however succeeded.",
		http.StatusOK,
		config.KeyLogoutRedirectURL,
	))
	public.GET(DefaultDeviceVerificationPath, h.fallbackHandler("", "", http.StatusOK, config.KeyDeviceVerificationURL))
	public.GET(DefaultPostDevicePath, h.fallbackHandler(
		"You successfully authenticated on your device!",
		"The Default Post Device URL is not set which is why you are seeing this fallback page. Your device login request however succeeded.",
		http.StatusOK,
		config.KeyDeviceDoneURL,
	))
	public.GET(DefaultErrorPath, h.DefaultErrorHandler)

	public.OPTIONS(RevocationPath, corsMiddleware(http.HandlerFunc(h.handleOptions)).ServeHTTP)
	public.POST(RevocationPath, corsMiddleware(http.HandlerFunc(h.revokeOAuth2Token)).ServeHTTP)
	public.OPTIONS(WellKnownPath, corsMiddleware(http.HandlerFunc(h.handleOptions)).ServeHTTP)
	public.GET(WellKnownPath, corsMiddleware(http.HandlerFunc(h.discoverOidcConfiguration)).ServeHTTP)
	public.OPTIONS(OauthAuthorizationServerPath, corsMiddleware(http.HandlerFunc(h.handleOptions)).ServeHTTP)
	public.GET(OauthAuthorizationServerPath, corsMiddleware(http.HandlerFunc(h.discoverOidcConfiguration)).ServeHTTP)
	public.OPTIONS(UserinfoPath, corsMiddleware(http.HandlerFunc(h.handleOptions)).ServeHTTP)
	public.GET(UserinfoPath, corsMiddleware(http.HandlerFunc(h.getOidcUserInfo)).ServeHTTP)
	public.POST(UserinfoPath, corsMiddleware(http.HandlerFunc(h.getOidcUserInfo)).ServeHTTP)

	public.OPTIONS(VerifiableCredentialsPath, corsMiddleware(http.HandlerFunc(h.handleOptions)).ServeHTTP)
	public.POST(VerifiableCredentialsPath, corsMiddleware(http.HandlerFunc(h.createVerifiableCredential)).ServeHTTP)

	public.POST(DeviceAuthPath, h.oAuth2DeviceFlow)
	public.GET(DeviceVerificationPath, h.performOAuth2DeviceVerificationFlow)
}

func (h *Handler) SetAdminRoutes(admin *httprouterx.RouterAdmin) {
	admin.POST(IntrospectPath, h.introspectOAuth2Token)
	admin.DELETE(DeleteTokensPath, h.deleteOAuth2Token)
}

// swagger:route GET /oauth2/sessions/logout oidc revokeOidcSession
//
// # OpenID Connect Front- and Back-channel Enabled Logout
//
// This endpoint initiates and completes user logout at the Ory OAuth2 & OpenID provider and initiates OpenID Connect Front- / Back-channel logout:
//
// - https://openid.net/specs/openid-connect-frontchannel-1_0.html
// - https://openid.net/specs/openid-connect-backchannel-1_0.html
//
// Back-channel logout is performed asynchronously and does not affect logout flow.
//
//	Schemes: http, https
//
//	Responses:
//	  302: emptyResponse
//
//	Extensions:
//	  x-ory-ratelimit-bucket: hydra-public-medium
func (h *Handler) performOidcFrontOrBackChannelLogout(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()

	handled, err := h.r.ConsentStrategy().HandleOpenIDConnectLogout(ctx, w, r)
	if errors.Is(err, consent.ErrUserRedirected) {
		return
	} else if err != nil {
		x.LogError(r, err, h.r.Logger())
		h.forwardError(w, r, err)
		return
	}

	if len(handled.FrontChannelLogoutURLs) == 0 {
		http.Redirect(w, r, handled.RedirectTo, http.StatusFound)
		return
	}

	// TODO How are we supposed to test this? Maybe with cypress? #1368
	t, err := template.New("logout").Parse(`<html>
<head>
    <meta http-equiv="refresh" content="7; URL={{ .RedirectTo }}">
</head>
<style type="text/css">
    iframe { position: absolute; left: 0; top: 0; height: 0; width: 0; border: none; }
</style>
<script>
    var total = {{ len .FrontChannelLogoutURLs }};
    var redir = {{ .RedirectTo }};

	var timeouts = [];
	var redirected = false;
	// Cancel all pending timeouts to avoid to call the frontchannel multiple times.
	window.onbeforeunload = () => {
		redirected = true;
		for (var i=0; i<timeouts.length; i++) {
			clearTimeout(timeouts[i]);
		}
		timeouts = [];
	};
	function setAndRegisterTimeout(fct, duration) {
		if (redirected) {
			return;
		}
		timeouts.push(setTimeout(fct, duration));
	}

	function redirect() {
		window.location.replace(redir);

		// In case replace failed try href
		setAndRegisterTimeout(function () {
			window.location.href = redir;
		}, 250);
	}

    function done() {
        total--;
        if (total < 1) {
			setAndRegisterTimeout(redirect, 500);
        }
    }

	setAndRegisterTimeout(redirect, 7000); // redirect after 7 seconds if e.g. an iframe doesn't load

	// If the redirect takes unusually long, show a message
	setTimeout(function () {
		document.getElementById("redir").style.display = "block";
	}, 2000);
</script>
<body>
<noscript>
    <p>
        JavaScript is disabled - you should be redirected in 5 seconds but if not, click <a
            href="{{ .RedirectTo }}">here</a> to continue.
    </p>
</noscript>

<p id="redir" style="display: none">
    Redirection takes unusually long. If you are not being redirected within the next seconds, click <a href="{{ .RedirectTo }}">here</a> to continue.
</p>

{{ range .FrontChannelLogoutURLs }}<iframe src="{{ . }}" onload="done(this)"></iframe>
{{ end }}
</body>
</html>`)
	if err != nil {
		x.LogError(r, err, h.r.Logger())
		h.forwardError(w, r, err)
		return
	}

	if err := t.Execute(w, handled); err != nil {
		x.LogError(r, err, h.r.Logger())
		h.forwardError(w, r, err)
		return
	}
}

