		t.Cleanup(adminTS.Close)
		reg.Config().MustSet(ctx, config.KeyAdminURL, adminTS.URL)
	}
	{
		n := negroni.New()
		n.Use(reqlog.NewMiddleware())
		n.UseFunc(httprouterx.TrimTrailingSlashNegroni)
